#include "deform_monitor_v3/risk_map/risk_map_exporter.hpp"
#include <fstream>
#include <iomanip>
#include <sstream>
#include <sys/stat.h>
namespace deform_monitor_v3 { namespace risk_map {
RiskMapExporter::~RiskMapExporter(){Stop();}
bool RiskMapExporter::Start(const RiskMapParams&p,const std::string&world){Stop();p_=p;if(!p_.export_enable||p_.export_directory.empty())return false;::mkdir(p_.export_directory.c_str(),0755);const std::string frames=p_.export_directory+"/frames";::mkdir(frames.c_str(),0755);std::ofstream m(p_.export_directory+"/manifest.json");if(!m)return false;m<<"{\n  \"schema_version\": 1,\n  \"world_frame\": \""<<world<<"\",\n  \"voxel_size\": "<<p_.voxel_size<<",\n  \"model_version\": \""<<p_.model_version<<"\",\n  \"calibration_version\": \""<<p_.calibration_version<<"\",\n  \"probabilities_calibrated\": "<<(p_.calibration_version!="uncalibrated"?"true":"false")<<"\n}\n";running_=true;worker_=std::thread(&RiskMapExporter::Worker,this);return true;}
void RiskMapExporter::Stop(){if(!running_)return;running_=false;cv_.notify_all();if(worker_.joinable())worker_.join();}
bool RiskMapExporter::Enqueue(const RiskMapFrame&f){if(!running_)return false;std::lock_guard<std::mutex>l(mutex_);if(q_.size()>=p_.export_queue_capacity){++dropped_;return false;}q_.push_back(f);cv_.notify_one();return true;}
void RiskMapExporter::Worker(){while(running_||!q_.empty()){RiskMapFrame f;{std::unique_lock<std::mutex>l(mutex_);cv_.wait_for(l,std::chrono::milliseconds(100),[this]{return!q_.empty()||!running_;});if(q_.empty())continue;f=std::move(q_.front());q_.pop_front();}Write(f);}}
bool RiskMapExporter::Write(const RiskMapFrame&f){std::ostringstream n;n<<p_.export_directory<<"/frames/frame_"<<std::setw(6)<<std::setfill('0')<<f.frame_index<<".csv";std::ofstream o(n.str());if(!o)return false;o<<"# stamp_sec="<<f.stamp.sec<<",stamp_nsec="<<f.stamp.nsec<<",reference_epoch="<<f.reference_epoch<<",dropped="<<dropped_<<"\n";o<<"ix,iy,iz,x,y,z,p_deformation,p_novel_occupancy,unknown_mask,knowledge_state,decision_cost,posterior_log_odds_def,posterior_log_odds_novel,log_bayes_factor_last,visibility_probability,dir_x,dir_y,dir_z,direction_confidence,event_semantics,region_id\n";o<<std::setprecision(9);for(const auto&v:f.voxels)o<<v.key.x<<','<<v.key.y<<','<<v.key.z<<','<<v.center_R.x()<<','<<v.center_R.y()<<','<<v.center_R.z()<<','<<v.p_deformation<<','<<v.p_novel_occupancy<<','<<(v.knowledge_state==KnowledgeState::UNKNOWN)<<','<<static_cast<int>(v.knowledge_state)<<','<<v.decision_cost<<','<<v.deformation_log_odds<<','<<v.novel_log_odds<<','<<v.last_log_bayes_factor<<','<<v.visibility_probability<<','<<v.principal_direction.x()<<','<<v.principal_direction.y()<<','<<v.principal_direction.z()<<','<<v.direction_confidence<<','<<static_cast<int>(v.semantics)<<','<<v.region_id<<'\n';return true;}
} }
